// Inspect payload and extract event type
const payload = $input.first().json;
const eventType = payload.type;

if (!eventType) {
  return [{ json: { ...payload, _error: 'missing_event_type' } }];
}

return [{ json: { ...payload, _event_type: eventType } }];

// Process order.created events
const payload = $input.first().json;
const { order_id, amount } = payload;

if (!order_id || !amount) {
  return [{ json: { ...payload, _error: 'missing_required_fields', _reason: 'order_id and amount required' } }];
}

return [{ json: { event_id: order_id, event_type: 'order.created', route: 'order_handler', handler: 'order_handler', handled: true } }];

// Process lead.captured events
const payload = $input.first().json;
const { name, email } = payload;

if (!name || !email) {
  return [{ json: { ...payload, _error: 'missing_required_fields', _reason: 'name and email required' } }];
}

return [{ json: { event_id: 'lead-' + name, event_type: 'lead.captured', route: 'lead_handler', handler: 'lead_handler', handled: true } }];

// Process ticket.created events
const payload = $input.first().json;
const { ticket_id, priority } = payload;

if (!ticket_id || !priority) {
  return [{ json: { ...payload, _error: 'missing_required_fields', _reason: 'ticket_id and priority required' } }];
}

return [{ json: { event_id: ticket_id, event_type: 'ticket.created', route: 'support_handler', handler: 'support_handler', handled: true } }];

// Collect unrouteable payloads to dead-letter queue
const payload = $input.first().json;
const eventType = payload._event_type || null;
const reason = payload._error || 'unknown_event_type';

return [{ json: { event_id: 'dlq-' + Date.now(), event_type: eventType, route: 'dead-letter', handler: null, handled: false, reason } }];

// Aggregate all results into final summary
const allItems = $input.all();
const routed = allItems.filter(i => i.json.handled === true);
const dead = allItems.filter(i => i.json.handled === false);

return [{
  json: {
    routed_events: routed.map(i => i.json),
    dead_letter: dead.map(i => i.json),
    total: allItems.length
  }
}];
